func compactJSON(s string) string {
	var buf bytes.Buffer
	if err := json.Compact(&buf, []byte(s)); err != nil {
		panic(fmt.Sprintf("compactJSON: %v", err))
	}
	return buf.String() + "\n"
}

func jsonExporter(fields ...string) cmdutil.Exporter {
	e := cmdutil.NewJSONExporter()
	e.SetFields(fields)
	return e
}

